            <tr style="border-top:1px solid var(--rule);">${o("<strong>∃ (PI)</strong>",!0)}${o("∃xA",!0)}${o(t("A(c) — c는 새 상항","A(c), c new"),!0)}${o(t("∃E 하위증명","∃E subproof"),!0)}</tr>
